// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Storage {
    uint256 private storedData; // Biến trạng thái lưu trữ

    // Khai báo sự kiện theo yêu cầu đề bài
    event ValueSet(address indexed who, uint256 newValue);

    // Hàm khởi tạo giá trị ban đầu khi deploy
    constructor (uint256 _init) { 
        storedData = _init;
    }

    // Hàm cập nhật giá trị và phát ra sự kiện
    function set (uint256 _value) public {
        storedData = _value;
        emit ValueSet(msg.sender, _value);
    }

    // Hàm đọc giá trị (view function không tốn gas)
    function get() public view returns (uint256) {
        return storedData;
    }
}

02_Greeting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Greeting {
    string private greeting;
    address public owner;

    // Khai báo sự kiện theo yêu cầu đề bài
    event GreetingChanged(address indexed changer, string newGreeting);

    // Modifier giới hạn chỉ có owner mới được gọi hàm
    modifier onlyOwner() {
        require(msg.sender == owner, "Not the owner");
        _;
    }

    // Constructor: gán người deploy là owner và thiết lập lời chào mặc định ban đầu
    constructor(string memory _g) {
        owner = msg.sender;
        greeting = _g;
    }

    // Hàm thay đổi lời chào (chỉ owner mới gọi được)
    function setGreeting(string memory _g) public onlyOwner {
        greeting = _g;
        emit GreetingChanged(msg.sender, _g);
    }

    // Hàm đọc lời chào (bất kỳ ai cũng gọi được, là hàm view không tốn gas)
    function greet() public view returns (string memory) {
        return greeting;
    }

    // Hàm đưa lời chào về mặc định 'Hello, World!' (chỉ owner mới gọi được)
    function resetGreeting() public onlyOwner {
        greeting = 'Hello, World!';
        emit GreetingChanged(msg.sender, 'Hello, World!');
    }
}

03_Counter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Counter {
    uint256 public count;
    uint256 public constant MAX = 100;

    // Khai báo các sự kiện theo yêu cầu đề bài
    event Incremented(address indexed user, uint256 newCount);
    event Decremented(address indexed user, uint256 newCount);
    event Reset(address indexed user);

    // Hàm tăng giá trị (giới hạn tối đa là 100)
    function increment() public {
        require(count < MAX, "Max limit reached at 100");
        count++;
        emit Incremented(msg.sender, count);
    }

    // Hàm giảm giá trị (không được nhỏ hơn 0)
    function decrement() public {
        require(count > 0, "Count is zero");
        count--;
        emit Decremented(msg.sender, count);
    }

    // Hàm đặt lại bộ đếm về 0 (chỉ thực hiện qua lời gọi tường minh)
    function reset() public {
        count = 0;
        emit Reset(msg.sender);
    }
}

04_Ownable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Ownable {
    address public owner;

    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not the owner");
        _;
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Invalid new owner");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }
}

contract ProtectedVault is Ownable {
    // Kế thừa Ownable, quản lý tiền gửi và rút ETH an toàn
    function deposit() public payable {
        require(msg.value > 0, "Must send ETH");
    }

    function withdraw(address payable to, uint256 amt) public onlyOwner {
        require(amt <= address(this).balance, "Insufficient balance");
        (bool success, ) = to.call{value: amt}("");
        require(success, "Transfer failed");
    }

    function contractBalance() public view returns (uint256) {
        return address(this).balance;
    }
}
